def transform(grid):
    # Mirror each motif through the central cross of 8s. The four panels
    # in each quadrant copy the nearest populated panel by reflection.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    rs=[r for r in range(h) if all(v==8 for v in grid[r])]
    cs=[c for c in range(w) if all(grid[r][c]==8 for r in range(h))]
    # From demos, complete a 2x2 block of panels by copying the motif in
    # the occupied one into the diagonally paired cell, mirrored vertically.
    # Also copy panel objects across adjacent vertical divider by reflection.
    for r in rs:
      above=next((q for q in rs if q<r),-1)+1
      below=next((q for q in rs if q>r),h)
      for y in range(above,r):
        yy=2*r-y
        if r+1<=yy<below:
          for x in range(w):
            if grid[y][x] not in (0,8) and grid[yy][x]==0: out[yy][x]=grid[y][x]
      for y in range(r+1,below):
        yy=2*r-y
        if above<=yy<r:
          for x in range(w):
            if grid[y][x] not in (0,8) and grid[yy][x]==0: out[yy][x]=grid[y][x]
    for c in cs:
      left=next((q for q in cs if q<c),-1)+1
      right=next((q for q in cs if q>c),w)
      for x in range(left,c):
        xx=2*c-x
        if c+1<=xx<right:
          for y in range(h):
            if grid[y][x] not in (0,8) and grid[y][xx]==0: out[y][xx]=grid[y][x]
      for x in range(c+1,right):
        xx=2*c-x
        if left<=xx<c:
          for y in range(h):
            if grid[y][x] not in (0,8) and grid[y][xx]==0: out[y][xx]=grid[y][x]
    return out
